import AppKit

/// Clip ▸ Remove Filler Words… — road map "cut-by-transcript" CT-3 (spec §11
/// TR-4, TR-7, TR-10): `detect_fillers`' answer as a count, the same spans
/// washed onto the timeline behind the sheet, and one `ripple_delete_ranges`
/// op when Remove is pressed.
///
/// **`SilenceSheetController`'s shape, without its controls.** TR-9 has no
/// threshold, padding or length to tune, so there is nothing to change and
/// `refresh()` runs only when the input does: at open, and after a
/// Transcribe run lands a filler transcript. The input is read once by the
/// command, as Remove Silences' is, because the document cannot change under
/// an open sheet — every editor action validates false while one is attached.
///
/// **The media with no filler transcript** (TR-7: the fillers come only from
/// an AssemblyAI transcript that asked for them) get a section of their own:
/// the cloud-only note, where the audio goes (R6-2), and one row per media
/// with its estimate and a Transcribe button
/// (`FillerSheetController+Transcribe.swift`). A run is one media's paid
/// upload, so Remove is disabled while it goes: Return cannot cut, and Cancel
/// is the only default-key path left, which stops the run.
final class FillerSheetController: NSViewController {
    /// Weak, like every sheet's back-reference: the document must be free to
    /// close even with a dialog mid-air.
    weak var document: ProjectDocument?
    /// Weak too. The candidate wash is the sheet's own view state, so the
    /// sheet sets it and the sheet clears it.
    weak var timeline: TimelineView?

    /// Everything a detection reads, taken off the document once — and again
    /// when a Transcribe run lands, which is why it is a `var`.
    var input: FillerDetector.Input
    /// Where the transcript cache lives; nil for a document that has none.
    let cacheDirectory: URL?
    /// Where the AssemblyAI key, the region and the endpoint come from —
    /// `TranscribeSheetController`'s injection points, for the probe.
    let store: any SecretStore
    let defaults: UserDefaults
    let environment: [String: String]

    /// What the sheet currently describes. Remove sends exactly these spans,
    /// so the readout and the edit cannot disagree.
    private(set) var outcome: FillerDetector.Outcome
    /// The media a Transcribe run is going for, or nil when none is.
    private(set) var runningMedia: UInt32?
    /// The last run's error sentence, shown in the note until the next run.
    var lastError: String?
    /// The run in flight, held for its whole life: `CloudTranscriber.run`
    /// hops onto its own queue under `[weak self]`, and a transcriber nobody
    /// retains never completes.
    var cloud: CloudTranscriber?
    /// The running run's Stop.
    var token: Transcriber.CancelToken?
    /// Set by the teardown, so a run that answers after the sheet has gone
    /// cannot put the wash back.
    var tornDown = false

    let summaryLabel = NSTextField(labelWithString: "")
    let noteLabel = NSTextField(wrappingLabelWithString: "")
    /// The TR-7 section's second line: R6-2's where, which region, and the
    /// deletion, set before any Transcribe button can be enabled.
    let hintLabel = NSTextField(wrappingLabelWithString: "")
    let cloudNoteLabel = NSTextField(wrappingLabelWithString: FillerSheetController.cloudOnlyNote)
    /// The TR-7 section: the note, the hint and the rows; hidden when every
    /// media in scope already has a filler transcript.
    let transcribeSection = NSStackView()
    let rowsStack = NSStackView()
    /// Set in `loadView`; the only implicitly-unwrapped optional here.
    private(set) var applyButton: NSButton!
    /// One per `outcome.needsTranscript`, in order.
    var mediaRows: [MediaRow] = []
    /// The rows' media a press could run: a cache directory and at least one
    /// clip that plays it from its file.
    var runnable: Set<UInt32> = []

    struct MediaRow {
        let media: UInt32
        let name: NSTextField
        let estimate: NSTextField
        let button: NSButton
    }

    /// TR-7's sentence.
    static let cloudOnlyNote =
        "Filler words are found only in an AssemblyAI transcript made with filler words — "
        + "transcription on this Mac does not report them. These files have none yet:"

    /// Generate Captions…' AssemblyAI sentence with "Transcribe" for
    /// "Generate" (R6-2, kept by TR-10).
    static func uploadHint(region: AssemblyAIConfiguration.Region) -> String {
        "The audio of these files is uploaded to AssemblyAI (\(region.displayName)), "
            + "transcribed with Universal-3.5 Pro, and deleted from AssemblyAI once the "
            + "words have been read back. Nothing is uploaded until Transcribe is pressed."
    }

    init(
        document: ProjectDocument, timeline: TimelineView?, input: FillerDetector.Input,
        cacheDirectory: URL?, store: any SecretStore = AssemblyAIConfiguration.store(),
        defaults: UserDefaults = .standard,
        environment: [String: String] = ProcessInfo.processInfo.environment
    ) {
        self.document = document
        self.timeline = timeline
        self.input = input
        self.cacheDirectory = cacheDirectory
        self.store = store
        self.defaults = defaults
        self.environment = environment
        self.outcome = FillerDetector.detect(input)
        super.init(nibName: nil, bundle: nil)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("FillerSheetController does not support NSCoder")
    }

    // MARK: - View

    override func loadView() {
        let width = sheetWidth - sheetInset * 2
        summaryLabel.font = DS.mono(11)
        summaryLabel.textColor = DS.textMuted
        noteLabel.font = DS.sans(11)
        noteLabel.textColor = DS.textFaint
        noteLabel.preferredMaxLayoutWidth = width
        cloudNoteLabel.font = DS.sans(12)
        cloudNoteLabel.textColor = DS.textStrong
        cloudNoteLabel.preferredMaxLayoutWidth = width
        hintLabel.font = DS.sans(11)
        hintLabel.textColor = DS.textMuted
        hintLabel.preferredMaxLayoutWidth = width
        // R6-2 before any button: the sentence is set here, ahead of the
        // first `rebuildRows`, so no Transcribe can be enabled without it.
        hintLabel.stringValue = Self.uploadHint(
            region: AssemblyAIConfiguration.region(defaults: defaults))

        rowsStack.orientation = .vertical
        rowsStack.alignment = .leading
        rowsStack.spacing = 8
        transcribeSection.orientation = .vertical
        transcribeSection.alignment = .leading
        transcribeSection.spacing = 8
        for view in [cloudNoteLabel, hintLabel, rowsStack] as [NSView] {
            transcribeSection.addArrangedSubview(view)
        }

        let content = sheetColumn([summaryLabel, noteLabel, transcribeSection])

        let cancelButton = sheetCancelButton(target: self, action: #selector(cancelClicked(_:)))
        applyButton = StickerButton(
            title: "Remove", style: .primary, target: self, action: #selector(applyClicked(_:)))
        view = makeSheetView(
            title: "Remove Filler Words",
            hint: "Each run of filler words — um, uh, er and the rest — is cut and the timeline "
                + "closes over it, as one edit. A cut is widened to the 32 ms speech grid so "
                + "the whole filler goes, but never into the words beside it, and its edges "
                + "snap inward to the frame grid. A filler that would cut into another clip's "
                + "word, a nest or a transition is left in.",
            content: content,
            buttonRow: makeButtonRow(
                cancel: cancelButton, apply: applyButton,
                leading: [sheetFootnote("markers keep their place")]))
        // A key saved or removed in Settings while this sheet is up reaches
        // its rows at once (spec §11 CJ-10).
        ModelKeys.observe(self, selector: #selector(modelKeysChanged(_:)))
        rebuildRows()
        refresh()
    }

    /// A key or the region changed in Settings: the hint names the region,
    /// and the rows and the note follow the key.
    @objc func modelKeysChanged(_ note: Notification) {
        hintLabel.stringValue = Self.uploadHint(
            region: AssemblyAIConfiguration.region(defaults: defaults))
        refresh()
    }

    // MARK: - Detection

    /// Re-detect and republish everything that follows from it: the readout,
    /// the rows' buttons, the note, the Remove button and the timeline's wash.
    func refresh() {
        outcome = FillerDetector.detect(input)
        summaryLabel.stringValue = summaryText()
        refreshRows()
        let note = noteText()
        noteLabel.stringValue = note
        noteLabel.isHidden = note.isEmpty
        applyButton?.isEnabled = !outcome.spans.isEmpty && runningMedia == nil
        timeline?.candidateSpans = outcome.spans
    }

    /// "3 cuts · removes 00:00:01:12", in the app's one spelling of a time.
    private func summaryText() -> String {
        guard !outcome.spans.isEmpty else { return "No cuts" }
        let cuts = outcome.spans.count == 1 ? "1 cut" : "\(outcome.spans.count) cuts"
        return cuts + " · removes " + ReelTime.format(outcome.removed, fps: input.fps, frames: true)
    }

    /// The second line, joined: what the count alone would hide.
    private func noteText() -> String {
        var notes: [String] = []
        if outcome.scope == .selected {
            notes.append("Only the selected clips are read.")
        }
        let dropped = outcome.dropped.count
        if dropped > 0 {
            notes.append(
                (dropped == 1 ? "1 filler is" : "\(dropped) fillers are")
                    + " left in: too short to cut, or cutting would reach another clip's word, "
                    + "a nest or a transition.")
        }
        let locked = outcome.locked.count
        if locked > 0 {
            notes.append(
                (locked == 1 ? "1 clip is" : "\(locked) clips are")
                    + " on a locked track, which the cut neither cuts nor moves, so "
                    + (locked == 1 ? "its" : "their") + " fillers were not read.")
        }
        if outcome.clips.isEmpty, outcome.needsTranscript.isEmpty, outcome.locked.isEmpty {
            notes.append("Nothing in scope plays speech from a media file, so nothing was read.")
        }
        notes.append(contentsOf: transcribeNotes())
        if let lastError { notes.append(lastError) }
        return notes.joined(separator: " ")
    }

    // MARK: - A Transcribe run's two ends

    /// A run has started for `media`: Remove goes off and its row reads Stop.
    func runStarted(media: UInt32) {
        runningMedia = media
        lastError = nil
        rebuildRows()
        refresh()
    }

    /// A run has ended: the input is read again, so a media that now has a
    /// filler transcript leaves the list and its fillers are counted.
    func runEnded(error: (any Error)?) {
        runningMedia = nil
        cloud = nil
        token = nil
        lastError = error?.localizedDescription
        if let document = document {
            input = FillerDetector.read(from: document, clips: nil)
        }
        rebuildRows()
        refresh()
    }

    // MARK: - Commit

    @objc private func cancelClicked(_ sender: Any?) {
        dismiss(self)
    }

    /// ONE `ripple_delete_ranges` for however many spans — one op, one undo
    /// step. The button is disabled when there is nothing to cut and while a
    /// run goes, and AppKit skips a disabled button for Return, so the guard
    /// below should be unreachable.
    @objc private func applyClicked(_ sender: Any?) {
        guard endSheetFieldEditing() else { return }
        let document = self.document
        dismiss(self)
        guard let document = document, !outcome.spans.isEmpty, runningMedia == nil else { return }
        document.applyEdit(
            "Remove Filler Words",
            [.rippleDeleteRanges(ranges: outcome.spans.map { (from: $0.start, to: $0.end) })])
    }

    /// The one teardown point, for Remove, Cancel, Escape and a window
    /// closing under the sheet alike: a run still going is stopped, and the
    /// wash comes off — it is not part of `TimelineView.update(...)`.
    override func viewDidDisappear() {
        super.viewDidDisappear()
        tornDown = true
        token?.cancel()
        timeline?.candidateSpans = []
    }
}

// MARK: - The menu command

/// The command half, at the foot of the file that owns the feature —
/// `SilenceSheetController.swift`'s precedent.
extension EditorViewController {

    /// Clip ▸ Remove Filler Words… — the body of the frozen file's one-line
    /// `@objc func removeFillerWords(_:)` forward. It beeps with no clip that
    /// plays sound from a media file, the validator's own question.
    func removeFillerWordsCommand() {
        guard let document = document, view.window?.attachedSheet == nil,
            Transcriber.hasTranscribableClip(in: document.editedProject.snapshot)
        else {
            NSSound.beep()
            return
        }
        let input = FillerDetector.read(from: document, clips: nil)
        // The wash is read while the sheet is up, and a running playhead
        // repaints over it several times a second.
        playback.pause()
        let sheet = FillerSheetController(
            document: document, timeline: timeline, input: input,
            cacheDirectory: document.cacheDirectory)
        presentAsSheet(sheet)
    }

    /// The half of `validateUserInterfaceItem` this file owns. nil means "not
    /// mine" and leaves the other answers alone. Keyed (spec §11 CJ-12): off,
    /// with the AssemblyAI sentence and the title suffix, only when no key is
    /// present and no media in scope has a current filler transcript.
    func validateFillerAction(_ action: Selector, item: NSMenuItem?) -> Bool? {
        guard action == #selector(EditorViewController.removeFillerWords(_:)) else { return nil }
        guard let document = document else { return false }
        let playable = Transcriber.hasTranscribableClip(in: document.editedProject.snapshot)
        let missing: ModelKey? =
            playable && !ModelKeys.present(.assemblyAI)
                && !FillerTranscriptPresence.any(in: document) ? .assemblyAI : nil
        return ModelKeys.mark(item, missing: missing, enabled: playable && missing == nil)
    }
}

/// Whether any media in Remove Filler Words' scope has a current filler
/// transcript (spec §11 CJ-12) — the menu validator's question, asked every
/// time a menu opens. One entry, kept while the edited project's handle, the
/// selection, the cache directory and `<cache>/transcripts/`'s modification
/// date are the ones it was answered for: the transcript cache posts nothing,
/// and a transcript written or removed renames an entry in that folder.
enum FillerTranscriptPresence {
    private struct Key {
        let project: ReelProject
        let selection: Set<UInt32>
        let cache: URL?
        let stamp: Date?
    }

    private static var memo: (key: Key, answer: Bool)?

    static func any(in document: ProjectDocument) -> Bool {
        let cache = document.cacheDirectory
        let folder = cache?.appendingPathComponent(MediaImporter.transcriptsKind, isDirectory: true)
        let stamp = folder.flatMap {
            try? $0.resourceValues(forKeys: [.contentModificationDateKey]).contentModificationDate
        }
        let key = Key(
            project: document.editedProject, selection: document.selection, cache: cache,
            stamp: stamp)
        if let memo, memo.key.project === key.project, memo.key.selection == key.selection,
            memo.key.cache == key.cache, memo.key.stamp == key.stamp
        {
            return memo.answer
        }
        let answer = !FillerDetector.read(from: document, clips: nil).clips.isEmpty
        memo = (key, answer)
        return answer
    }
}
import AppKit

// MARK: - Sheet: the media with no filler transcript

/// Remove Filler Words' TR-7 section (spec §11 TR-2, TR-10): one row per
/// media in scope with no AssemblyAI transcript made with filler words — its
/// name, what one press would upload and cost (`CloudEstimate.describe` of
/// the very request the run sends, `FillerTranscription`), and a Transcribe
/// button — and the run that button starts.
///
/// **One media per press.** The request is the media's previous one plus
/// fillers (`FillerTranscription.options`), and the run only writes the
/// media's transcript cache: no caption is placed and no undo step is made.
/// When it lands the sheet reads its input again (`runEnded`), so the media
/// leaves the list and its fillers join the count.
///
/// **The button is disabled** with no credential (the note names Settings),
/// with no cache directory (the note says to save), with no clip that plays
/// the media from its file, and while any run goes — except the running
/// row's, which reads Stop and cancels it.
extension FillerSheetController {

    /// The rows, made again from `input.needsTranscript`: called at open, when
    /// a run starts and when it ends.
    func rebuildRows() {
        for view in rowsStack.arrangedSubviews {
            rowsStack.removeArrangedSubview(view)
            view.removeFromSuperview()
        }
        mediaRows = []
        runnable = []
        let snapshot = document?.editedProject.snapshot
        let maps: SourceMaps = document?.editedProject.sourceMap ?? { _ in nil }
        let urls = document?.mediaURLs() ?? [:]
        var records: [UInt32: MediaSnapshot] = [:]
        for entry in snapshot?.media ?? [] { records[entry.id] = entry }
        let textWidth = sheetWidth - sheetInset * 2 - 120
        for media in input.needsTranscript {
            let jobs =
                snapshot.map {
                    FillerTranscription.jobs(for: media, in: $0, urls: urls, maps: maps)
                } ?? []
            let name = NSTextField(labelWithString: records[media]?.name ?? "Media \(media)")
            name.font = DS.sans(13)
            name.textColor = DS.textStrong
            name.lineBreakMode = .byTruncatingMiddle
            name.preferredMaxLayoutWidth = textWidth
            let estimate = NSTextField(wrappingLabelWithString: "")
            estimate.font = DS.mono(11)
            estimate.textColor = DS.textMuted
            estimate.preferredMaxLayoutWidth = textWidth
            if let cache = cacheDirectory,
                let priced = FillerTranscription.estimate(
                    jobs: jobs, media: records, cacheDirectory: cache)
            {
                estimate.stringValue = CloudEstimate.describe(priced, fps: input.fps)
                estimate.toolTip = CloudEstimate.rateSentence(speakers: priced.speakers)
                runnable.insert(media)
            } else {
                estimate.stringValue = cacheDirectory == nil
                    ? "Save the project to transcribe it"
                    : "No clip plays this file, so it cannot be transcribed"
            }
            if media == runningMedia { estimate.stringValue = "Starting…" }
            let button = StickerButton(
                title: "Transcribe", style: .secondary, target: self,
                action: #selector(transcribeClicked(_:)))
            let text = NSStackView(views: [name, estimate])
            text.orientation = .vertical
            text.alignment = .leading
            text.spacing = 2
            text.widthAnchor.constraint(equalToConstant: textWidth).isActive = true
            let line = NSStackView(views: [text, button])
            line.orientation = .horizontal
            line.alignment = .centerY
            line.spacing = 12
            rowsStack.addArrangedSubview(line)
            mediaRows.append(MediaRow(media: media, name: name, estimate: estimate, button: button))
        }
        transcribeSection.isHidden = input.needsTranscript.isEmpty
    }

    /// Whether a key resolves, through the sheet's own store and environment.
    var hasCredential: Bool {
        ModelKeys.present(.assemblyAI, store: store, environment: environment)
    }

    /// The buttons' titles and states: Stop on the running row, Transcribe
    /// on every other, enabled only when a press could run.
    func refreshRows() {
        let idle = runningMedia == nil
        let hasCredential = self.hasCredential
        for row in mediaRows {
            let title = row.media == runningMedia ? "Stop" : "Transcribe"
            if row.button.title != title {
                row.button.title = title
                row.button.invalidateIntrinsicContentSize()
            }
            if row.media == runningMedia {
                row.button.isEnabled = true
                continue
            }
            ModelKeys.mark(
                row.button, missing: hasCredential ? nil : .assemblyAI,
                enabled: idle && hasCredential && runnable.contains(row.media))
        }
    }

    /// What the rows need said: no key, and nowhere to keep a transcript.
    func transcribeNotes() -> [String] {
        guard !input.needsTranscript.isEmpty else { return [] }
        var notes: [String] = []
        if !hasCredential { notes.append(ModelKeys.sentence(.assemblyAI)) }
        if cacheDirectory == nil {
            notes.append(
                "This project has nowhere to keep its transcript cache, so it cannot be "
                    + "transcribed with AssemblyAI. Save it first.")
        }
        return notes
    }

    // MARK: - The run

    /// Transcribe on an idle row starts its run; Stop on the running row
    /// cancels it.
    @objc func transcribeClicked(_ sender: Any?) {
        guard let button = sender as? NSButton,
            let row = mediaRows.first(where: { $0.button === button })
        else { return }
        if row.media == runningMedia {
            token?.cancel()
            return
        }
        guard runningMedia == nil else {
            NSSound.beep()
            return
        }
        transcribe(media: row.media)
    }

    /// One media's paid upload, on `CloudTranscriber.run`'s own queue, with
    /// the request `FillerTranscription` builds; the completion arrives on
    /// main and goes to `runEnded`.
    func transcribe(media: UInt32) {
        guard let document = document, let cache = cacheDirectory,
            let credential = AssemblyAIConfiguration.credential(
                store: store, environment: environment)
        else {
            NSSound.beep()
            return
        }
        let client: AssemblyAIClient
        do {
            client = AssemblyAIClient(
                base: try AssemblyAIConfiguration.baseURL(defaults: defaults),
                credential: credential)
        } catch {
            lastError = error.localizedDescription
            refresh()
            return
        }
        let snapshot = document.editedProject.snapshot
        let jobs = FillerTranscription.jobs(
            for: media, in: snapshot, urls: document.mediaURLs(),
            maps: document.editedProject.sourceMap)
        guard !jobs.isEmpty else {
            NSSound.beep()
            return
        }
        var records: [UInt32: MediaSnapshot] = [:]
        for entry in snapshot.media { records[entry.id] = entry }
        let run = CloudTranscriber(client: client, cacheDirectory: cache, media: records)
        let cancel = Transcriber.CancelToken()
        cloud = run
        token = cancel
        runStarted(media: media)
        run.run(
            jobs: jobs,
            options: FillerTranscription.options(
                for: MediaTranscript.readStamp(for: media, in: cache)),
            refresh: FillerTranscription.refresh,
            frame: max(snapshot.canvas.fps.frameDuration, 1),
            pages: CaptionPages.Request(
                style: .subtitles,
                canvas: CGSize(width: snapshot.canvas.width, height: snapshot.canvas.height)),
            cancel: cancel,
            progress: { [weak self] fraction, detail in
                DispatchQueue.main.async { self?.progressed(media, fraction, detail) }
            },
            completion: { [weak self] outcome in
                guard let self = self, !self.tornDown else { return }
                if case .failure(let error) = outcome {
                    self.runEnded(error: error)
                } else {
                    self.runEnded(error: nil)
                }
            })
    }

    /// The running row's estimate line, while it runs.
    private func progressed(_ media: UInt32, _ fraction: Double, _ detail: String) {
        guard media == runningMedia, let row = mediaRows.first(where: { $0.media == media })
        else { return }
        let percent = "\(Int((min(max(fraction, 0), 1) * 100).rounded())) %"
        row.estimate.stringValue = (detail.isEmpty ? "Transcribing" : detail) + " · " + percent
    }
}
import Foundation

/// Remove Filler Words' re-transcribe (road map "cut-by-transcript" CT-3, spec
/// §11 TR-2, TR-7, TR-10): the request, the jobs and the estimate one press
/// of the sheet's Transcribe button sends for one media, shared by the sheet
/// (`FillerSheetController+Transcribe.swift`) and its mirror,
/// `transcribe_for_fillers` (`AgentServer+Fillers.swift`), so the two cannot
/// send different requests or quote different prices.
///
/// It holds no document. The jobs come from a snapshot and its media URLs,
/// and the estimate from a cache directory, all passed by value — which is
/// what lets the tool read them in one main-thread hop and run off main.
///
/// **TR-10's request.** The media's PREVIOUS request is kept — the marker's
/// language, speaker labels and vocabulary — so the filler transcript is the
/// same transcript as before with the fillers in it; the shipped models,
/// `disfluencies: true` and `refresh: true` are added. With no marker it is
/// detection, no speakers and no vocabulary. `refresh` is what makes a media
/// whose caption transcript is current upload again: `CloudEstimate.fate`
/// and `CloudTranscriber.transcribe` both judge currency for `.captions`,
/// which ignores `disfluencies` (TR-2).
enum FillerTranscription {

    /// Always on: a media in the sheet's list has a transcript that serves
    /// captions or none, and either way it must be fetched again.
    static let refresh = true

    /// The marker's request with fillers asked for, or detection with none.
    static func options(for marker: TranscriptStamp?) -> TranscriptOptions {
        TranscriptOptions(
            speechModels: TranscriptOptions.shippedModels,
            languageCode: marker?.languageCode,
            speakerLabels: marker?.speakerLabels ?? false,
            keytermsPrompt: marker?.keytermsPrompt ?? [],
            disfluencies: true)
    }

    /// `Transcriber.jobs` over the snapshot's clips that play `media`; the
    /// clips it refuses (a reversed one, one whose audio is off, a missing
    /// file) are left out, as a caption run leaves them. `maps` are the
    /// source maps of the snapshot's handle, so a ramped clip's job follows
    /// its map (spec §11 SR-20 (d)).
    static func jobs(
        for media: UInt32, in snapshot: ProjectSnapshot, urls: [UInt32: URL], maps: SourceMaps
    ) -> [Transcriber.Job] {
        let clips = snapshot.clips.filter { clip in
            guard case .media(let id, _, _) = clip.source else { return false }
            return id == media
        }
        return Transcriber.jobs(for: clips, in: snapshot, urls: urls, maps: maps).jobs
    }

    /// What one press would upload and cost, by `CloudEstimate`'s own rules
    /// over the same request the run sends; nil when there is nothing to run.
    static func estimate(
        jobs: [Transcriber.Job], media: [UInt32: MediaSnapshot], cacheDirectory: URL
    ) -> CloudEstimate? {
        guard !jobs.isEmpty else { return nil }
        let facts = CloudEstimate.facts(jobs: jobs, media: media, cacheDirectory: cacheDirectory)
        return CloudEstimate(
            facts: facts, options: options(for: facts.first?.marker), refresh: refresh)
    }
}

## Cutting false starts with the assistant

A false start is a phrase the speaker abandoned or said again. Deciding what counts is a judgement about meaning, so there is no menu command for it. Ask the assistant in the inspector's Assistant tab instead, for example "cut the false start at the beginning of this clip." The assistant:

1. reads the clip's words and their times;
2. tells you which words it will cut;
3. cuts them in one step, each cut running from the first cut word's start to the last cut word's end.

